-- Biochemistry Ch2: Enzymes — RE-ENGINEERED (quality sweep)
-- Replaces 26 flagged questions in place (UPDATE by id, so student attempt history stays linked).
-- Defects fixed: A fake-hard/readback, B1 self-justifying key, B2 odd-one-out, B3 nonsense distractor,
-- B4 stem-telegraph, B5 easy-dressed-up. Grounded in LibreTexts Biochemistry. Idempotent; safe to re-run.
-- distractor_category note: agent categories 'overgeneralization'->'misconception', 'true_but_irrelevant'->'partial_truth'
-- to satisfy the question_distractor_metadata CHECK constraint.

BEGIN;

-- Q1 [Local Conditions: Temperature, pH & Salinity] modes=['B3', 'B1'] ans=A medium skill2
UPDATE questions SET
  question_text = 'A purified protease shows maximal activity near pH 6. Its catalytic mechanism requires that a single active-site side chain, which has an apparent pKa of about 6, be in its deprotonated form. A researcher assays the enzyme in a well-buffered solution at pH 4 — a mild shift that does not unfold the protein. What is the most likely effect on catalytic rate, and why?',
  options = '[{"label": "A", "text": "Activity falls, because at pH 4 the residue is largely protonated and is no longer in the state the mechanism requires."}, {"label": "B", "text": "Activity falls, because at pH 4 the residue is largely deprotonated and is no longer in the state the mechanism requires."}, {"label": "C", "text": "Activity rises, because at pH 4 the residue is largely protonated, which is the state the mechanism requires."}, {"label": "D", "text": "Activity is unchanged, because a mild pH shift affects only substrate binding and not the charge of catalytic residues."}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' LibreTexts explains that ''key side chains necessary for catalysis must be in the correct protonation state,'' using the example of a side chain ''with an apparent pKa of around 6, [that] must be deprotonated for optimal activity of trypsin, which shows increases in activity with pH centered at pH 6'' (lines 28511-28513). The text also gives the ''+2 rule'': when the pH is about 2 units below the pKa, the group is roughly 99% protonated, and when the pH is about 2 units above the pKa, it is roughly 99% deprotonated (lines 3102-3113). Here the assay pH (4) is about 2 units below the residue''s pKa (~6), so the side chain is driven into its protonated form — the opposite of the deprotonated state catalysis requires — and activity drops even without any unfolding. (Choice A) is correct: at pH 4 (2 units below the pKa of 6) the residue is largely protonated, which is not the deprotonated state the mechanism needs, so the rate falls. (Choice B) is incorrect: this reverses the +2 rule — lowering the pH below the pKa protonates the group, it does not deprotonate it, so the stated reason contradicts the direction of the acid-base equilibrium even though the predicted drop happens to be right for the wrong reason. (Choice C) is incorrect: it correctly notes the residue is protonated at pH 4 but then inverts the mechanism''s requirement — the stem specifies the deprotonated form is catalytically active, so protonation lowers, not raises, activity. (Choice D) is incorrect: pH does not act only on substrate binding; the text lists that pH can alter catalysis (kcat) by changing the protonation state of catalytic side chains, so a shift that protonates an essential residue changes turnover directly, not merely binding. This is a Scientific Reasoning and Problem Solving question because you must apply the pH–pKa relationship (the +2 rule) to predict the protonation state of a catalytic residue at a given pH and connect that state to the enzyme''s activity.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '04380d86-f9f5-4e90-bfde-fbbbf1f9fc7c';
DELETE FROM question_distractor_metadata WHERE question_id = '04380d86-f9f5-4e90-bfde-fbbbf1f9fc7c';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('04380d86-f9f5-4e90-bfde-fbbbf1f9fc7c', 'B', 'reversed_relationship', 'reverses the +2 rule: assumes lowering pH below pKa deprotonates the residue'),
  ('04380d86-f9f5-4e90-bfde-fbbbf1f9fc7c', 'C', 'misconception', 'inverts which protonation state is catalytically active'),
  ('04380d86-f9f5-4e90-bfde-fbbbf1f9fc7c', 'D', 'misconception', 'believes pH affects only substrate binding (Km), never the catalytic residue''s charge (kcat)');

-- Q2 [Enzyme Regulation (Allosteric, Feedback, Covalent Modification, Zymogens)] modes=['B4', 'B5'] ans=C medium skill2
UPDATE questions SET
  question_text = 'A researcher studies a metabolic enzyme that is inactive until a specific cellular stimulus appears. Once the stimulus activates the enzyme, its catalytic activity persists even after the researcher removes the stimulus, washes away all small molecules and ATP, and returns the cell to resting conditions — the enzyme cannot be switched back to its inactive state by the cell''s normal machinery. Which regulatory mechanism best accounts for this behavior?',
  options = '[{"label": "A", "text": "Phosphorylation of a serine side chain by a protein kinase"}, {"label": "B", "text": "Binding of an allosteric activator at a site distinct from the active site"}, {"label": "C", "text": "Cleavage of an inactive precursor by limited proteolysis"}, {"label": "D", "text": "Sequestration of the enzyme by a reversibly bound inhibitor protein"}]'::jsonb,
  correct_answer = 'C',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' Regulatory mechanisms differ in a decisive property: whether they can be reversed by the cell. The textbook contrasts reversible mechanisms — protein phosphorylation is ''the reversible addition of a phosphoryl group'' whose reversibility is ''attributed to the actions of kinases and phosphatases'' — with zymogen activation, in which inactive precursors ''become activated on limited proteolysis'' by permanent peptide-bond cleavage. The key here is that the enzyme stays active after every stimulus and small molecule is removed, so only an irreversible mechanism fits. (Choice C) is correct: an inactive precursor (zymogen) is activated by limited proteolysis — peptide bonds are hydrolytically cleaved and cannot be re-formed by the cell, so once cut the enzyme remains active regardless of whether the original stimulus is present, exactly the persistence described. (Choice A) is incorrect: this reflects the misconception that any covalent activation is permanent; phosphorylation is reversible, and a phosphatase would remove the phosphoryl group and switch the enzyme off once the activating signal disappears, so activity would not persist. (Choice B) is incorrect: allosteric activation is non-covalent and depends on the activator staying bound, so washing away small molecules would let the modulator dissociate and the enzyme would revert to its inactive conformation. (Choice D) is incorrect: reversible inhibitor binding is governed by equilibrium, so removing or diluting the components would release the enzyme rather than lock in a persistent state. This is a Scientific Reasoning and Problem Solving question because you must apply the principle that a regulatory change surviving removal of all stimuli and small molecules must be irreversible, which points to proteolytic activation of a zymogen rather than any reversible covalent or non-covalent mechanism.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '06738ec8-0cfb-4685-be16-119f21663264';
DELETE FROM question_distractor_metadata WHERE question_id = '06738ec8-0cfb-4685-be16-119f21663264';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('06738ec8-0cfb-4685-be16-119f21663264', 'A', 'misconception', 'assumes covalent modification is always irreversible'),
  ('06738ec8-0cfb-4685-be16-119f21663264', 'B', 'misconception', 'confuses persistent activation with reversible allosteric binding'),
  ('06738ec8-0cfb-4685-be16-119f21663264', 'D', 'adjacent_fact', 'treats equilibrium-governed inhibitor binding as a stable off-switch');

-- Q3 [Irreversible Inhibition] modes=['B1', 'B2'] ans=A hard skill2
UPDATE questions SET
  question_text = 'Iodoacetamide abolishes the activity of a purified enzyme, and the loss is not reversed by dialysis, consistent with covalent modification of an active-site cysteine. A researcher repeats the experiment but first pre-incubates the enzyme to saturation with a reversible competitive inhibitor, then adds iodoacetamide, and finally removes the reversible inhibitor by dialysis. Under this protocol, most of the enzyme''s activity is retained. Which explanation best accounts for the protective effect of the pre-incubation?',
  options = '[{"label": "A", "text": "Occupancy of the active site by the reversible ligand physically shielded the critical cysteine from the modifying reagent"}, {"label": "B", "text": "The reversible inhibitor chemically reacted with iodoacetamide in solution, consuming it before it could reach the enzyme"}, {"label": "C", "text": "Iodoacetamide was bound only noncovalently, so dialysis stripped it away together with the reversible inhibitor"}, {"label": "D", "text": "Saturating the enzyme with ligand raised the maximum velocity enough to offset the covalent modification"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' Irreversible covalent inhibitors such as iodoacetamide permanently inactivate an enzyme by modifying an essential side chain (for example, an active-site cysteine), and the text describes a standard control in which one can ''protect the active site with saturating concentrations of a ligand that binds reversibly at the active site,'' so that ''the critical side chain would be protected from chemical modification'' (lines 27800-27805). Because the reversible ligand transiently occupies the active site, it sterically blocks the reagent''s access to the catalytic cysteine; once the reagent is washed out and the reversible ligand is dialyzed away, the unmodified enzyme is active again. (Choice A) is correct: bound reversible ligand physically occludes the reactive residue, so fewer active sites become covalently modified and activity is preserved after dialysis. (Choice B) is incorrect: the protection arises from active-site occupancy, not from a bimolecular reaction between the two molecules in solution; a reversible active-site inhibitor is not a nucleophile scavenger for iodoacetamide, and this misconception treats steric shielding as chemical quenching. (Choice C) is incorrect because iodoacetamide forms a covalent, non-dialyzable bond, as shown by the original experiment in which dialysis alone failed to restore activity; this reflects the error of assuming all inhibitors dissociate and can be dialyzed away. (Choice D) is incorrect because covalent modification of the catalytic residue lowers the fraction of functional enzyme and thus lowers \(V_{max}\); it cannot be overridden by adding more ligand, which is the misapplied idea that excess substrate rescues activity as it does for reversible competitive inhibition. This is a Scientific Reasoning and Problem Solving question because you must apply the logic of an active-site protection experiment to infer that steric occupancy, not a chemical or kinetic effect, explains why pre-incubation preserves activity against an irreversible modifier.',
  difficulty = 'hard',
  cognitive_skill = 2
WHERE id = '249a1513-4a82-4b25-93ff-5e44b176b05d';
DELETE FROM question_distractor_metadata WHERE question_id = '249a1513-4a82-4b25-93ff-5e44b176b05d';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('249a1513-4a82-4b25-93ff-5e44b176b05d', 'B', 'misconception', 'confuses steric shielding with chemical quenching of the reagent'),
  ('249a1513-4a82-4b25-93ff-5e44b176b05d', 'C', 'misconception', 'assumes all inhibitors are reversible and dialyzable'),
  ('249a1513-4a82-4b25-93ff-5e44b176b05d', 'D', 'misconception', 'misapplies excess-substrate/Vmax rescue from competitive to irreversible inhibition');

-- Q4 [Active Site, Lock-and-Key & Induced Fit] modes=['B3'] ans=A medium skill2
UPDATE questions SET
  question_text = 'A researcher crystallizes a hydrolase in two states: alone, and bound to its substrate. Comparing the structures, she finds that the enzyme''s active site is more open in the unbound form and closes down around the substrate after binding, becoming more geometrically complementary to it. Which conclusion is best supported by this observation?',
  options = '[{"label": "A", "text": "The enzyme follows the induced-fit model of substrate binding"}, {"label": "B", "text": "The enzyme follows the lock-and-key model of substrate binding"}, {"label": "C", "text": "The substrate binds at an allosteric site rather than the active site"}, {"label": "D", "text": "The substrate is covalently modified during the binding event"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The textbook distinguishes two models of enzyme-substrate binding: a lock-and-key model, "in which the reactant fits the exact shape of the enzyme''s binding site," versus an induced-fit model, "in which contact between the reactant and the protein changes the protein''s shape, allowing it to bind" (lines 731-733). It further notes that in the induced-fit model "substrate interaction causes the enzyme''s shape to change to better fit the substrate" (lines 738-739). The observation here—an active site that reshapes itself around the substrate to become more complementary—is the defining signature of induced fit. (Choice A) is correct: a binding-triggered conformational change that improves complementarity between enzyme and substrate is exactly what the induced-fit model predicts. (Choice B) is incorrect: this reflects the common misconception that any tight enzyme-substrate fit is lock-and-key; lock-and-key specifically requires that the substrate fit the pre-existing active-site shape "without further modification to the enzyme''s shape" (line 739), which contradicts the observed conformational change. (Choice C) is incorrect: a student may assume that any change in enzyme conformation implies allosteric regulation, but an allosteric site is a location other than the active site where a regulator binds; here the shape change occurs at the active site as the substrate binds, so this is catalytic binding, not allosteric regulation. (Choice D) is incorrect: this confuses a change in the enzyme''s conformation with a change in the substrate; the structures show the enzyme''s shape adjusting, not the substrate being chemically altered, and covalent modification of the substrate is a catalytic step, not what these binding structures demonstrate. This is a Scientific Reasoning and Problem Solving question because you must apply the definitions of the lock-and-key and induced-fit models to interpret experimental structural data.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '3233147e-3b20-4a25-ae3a-c8c39c9d25ef';
DELETE FROM question_distractor_metadata WHERE question_id = '3233147e-3b20-4a25-ae3a-c8c39c9d25ef';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('3233147e-3b20-4a25-ae3a-c8c39c9d25ef', 'B', 'misconception', 'confuses lock-and-key with induced fit'),
  ('3233147e-3b20-4a25-ae3a-c8c39c9d25ef', 'C', 'misconception', 'assumes any conformational change means allosteric regulation'),
  ('3233147e-3b20-4a25-ae3a-c8c39c9d25ef', 'D', 'misconception', 'attributes enzyme conformational change to substrate modification');

-- Q5 [Enzyme Regulation (Allosteric, Feedback, Covalent Modification, Zymogens)] modes=['B4'] ans=A medium skill2
UPDATE questions SET
  question_text = 'Aspartate transcarbamylase (ATCase) catalyzes the committed step of pyrimidine synthesis, producing the precursor to CTP and UTP. As expected, high levels of CTP allosterically inhibit ATCase. Unexpectedly, ATP — a purine nucleotide made in a separate pathway — allosterically activates ATCase. What does this activation by ATP most likely accomplish for the cell?',
  options = '[{"label": "A", "text": "It raises pyrimidine output when purine levels are high, keeping the two nucleotide pools balanced"}, {"label": "B", "text": "It slows the reverse reaction so that more carbamoyl aspartate product is retained by the pathway"}, {"label": "C", "text": "It signals that ATP is the true end product, triggering normal feedback inhibition of the pathway"}, {"label": "D", "text": "It donates a phosphate that covalently modifies ATCase and locks the enzyme in its active form"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The textbook describes aspartate transcarbamylase as the enzyme catalyzing the first step of pyrimidine (CTP/UTP) synthesis, where ''the end products of the pathway, CTP and UTP, feed back and allosterically inhibit the enzyme. In contrast, ATP is an allosteric activator,'' and it states this cross-regulation ''prevents a buildup of pyrimidine nucleotides over purine nucleotides since equal amounts are needed for nucleic acid synthesis'' (lines 21091). ATP and CTP bind distinct allosteric (heterotropic) sites and shift ATCase between its inactive T and active R states without any covalent change. (Choice A) is correct: because DNA and RNA require roughly equal purine and pyrimidine nucleotides, a high purine (ATP) level acts as a signal that pyrimidine synthesis should be accelerated to match, so ATP activation balances the two pools — the reasoning the textbook gives for cross-pathway activation. (Choice B) is incorrect: allosteric activation raises the enzyme''s catalytic activity in the forward direction; it does not work by suppressing a reverse reaction, and framing regulation as retention of the intermediate carbamoyl aspartate confuses allosteric control with thermodynamic reversibility. (Choice C) is incorrect: ATP is a purine made in a separate pathway, not the end product of pyrimidine synthesis — the pyrimidine end products CTP and UTP are the feedback inhibitors, so treating ATP as an inhibitory end product reverses its actual activating role. (Choice D) is incorrect: ATP here binds a separate allosteric site to shift the T/R equilibrium, which is noncovalent allosteric regulation; it does not phosphorylate ATCase, and this choice confuses allosteric activation with covalent modification. This is a Scientific Reasoning and Problem Solving question because you must apply the logic of cross-pathway allosteric regulation to infer why a purine nucleotide would activate a pyrimidine-synthesizing enzyme.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '3415a166-143a-4ca6-8df6-b8d0f9a4e9c7';
DELETE FROM question_distractor_metadata WHERE question_id = '3415a166-143a-4ca6-8df6-b8d0f9a4e9c7';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('3415a166-143a-4ca6-8df6-b8d0f9a4e9c7', 'B', 'misconception', 'confuses allosteric activation with control of the reverse/thermodynamic direction'),
  ('3415a166-143a-4ca6-8df6-b8d0f9a4e9c7', 'C', 'reversed_relationship', 'misidentifies ATP as the pathway end product and casts its role as inhibitory feedback'),
  ('3415a166-143a-4ca6-8df6-b8d0f9a4e9c7', 'D', 'misconception', 'conflates noncovalent allosteric activation with covalent (phosphorylation) modification');

-- Q6 [Local Conditions: Temperature, pH & Salinity] modes=['B4'] ans=C medium skill2
UPDATE questions SET
  question_text = 'A human enzyme is assayed at 20 °C and shows a reaction velocity of 4 μmol/min. As a rule of thumb, the reaction velocity roughly doubles for each 10 °C rise in temperature until the enzyme approaches its optimum. If the enzyme''s optimum lies near 40 °C, which velocity is the researcher most likely to measure at 40 °C?',
  options = '[{"label": "A", "text": "About 8 μmol/min"}, {"label": "B", "text": "About 12 μmol/min"}, {"label": "C", "text": "About 16 μmol/min"}, {"label": "D", "text": "About 40 μmol/min"}]'::jsonb,
  correct_answer = 'C',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' Below an enzyme''s optimum temperature, activity rises with heat much like any uncatalyzed reaction; LibreTexts notes the "general rule of thumb that reaction velocities double for each increase of 10 oC" (line 28492) and that "From 0 to about 40-50 oC, enzyme activity usually increases." Going from 20 °C to 40 °C is two 10 °C steps, so the velocity doubles twice: \(4 \times 2 \times 2 = 16\) μmol/min. (Choice A) is incorrect: 8 μmol/min applies a single doubling, treating the change as one 10 °C step (20→30) rather than the two steps needed to reach 40 °C. (Choice B) is incorrect: 12 μmol/min comes from adding 4 μmol/min per 10 °C step (4→8→12), an additive/linear model, but the rule of thumb is multiplicative doubling, not a fixed increment. (Choice C) is correct: two 10 °C increases each double the rate, giving \(4 \to 8 \to 16\) μmol/min, consistent with the doubling rule below the optimum. (Choice D) is incorrect: 40 μmol/min presumes activity scales directly with absolute temperature (a tenfold jump to match 40 °C), a misreading of the qualitative rule as a proportionality to the temperature reading itself. This is a Scientific Reasoning and Problem Solving question because you must apply the doubling-per-10 °C rule across a two-step temperature increase rather than simply recall it.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '3e350fae-4f66-4350-81ec-13dde888e309';
DELETE FROM question_distractor_metadata WHERE question_id = '3e350fae-4f66-4350-81ec-13dde888e309';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('3e350fae-4f66-4350-81ec-13dde888e309', 'A', 'misconception', 'applied only one doubling step instead of two'),
  ('3e350fae-4f66-4350-81ec-13dde888e309', 'B', 'misconception', 'used additive/linear increments instead of multiplicative doubling'),
  ('3e350fae-4f66-4350-81ec-13dde888e309', 'D', 'misconception', 'treated velocity as directly proportional to the absolute temperature value');

-- Q7 [Cofactors, Coenzymes & Vitamins] modes=['B2', 'B4', 'B5'] ans=A medium skill2
UPDATE questions SET
  question_text = 'A biochemist characterizes an oxidoreductase and finds that it removes two electrons and a proton (a hydride) from its substrate in a single oxidation step. The cofactor responsible stays tightly bound to the enzyme throughout catalysis; rather than leaving the active site, it is re-oxidized in place by a downstream electron acceptor before the enzyme can turn over again. Which vitamin-derived coenzyme is this enzyme most likely using?',
  options = '[{"label": "A", "text": "FAD (from vitamin B2)"}, {"label": "B", "text": "NAD+ (from vitamin B3)"}, {"label": "C", "text": "TPP (from vitamin B1)"}, {"label": "D", "text": "PLP (from vitamin B6)"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The textbook distinguishes coenzymes that bind loosely and dissociate (acting as substrates) from prosthetic groups that stay tightly or covalently attached and must be regenerated in place each catalytic cycle. It states that ''FAD and its reduced form, FADH2, are tightly or covalently attached to an enzyme, so FAD must be regenerated in each catalytic cycle,'' and that FAD oxidation is a hydride transfer that ''removes 2 electrons from the substrate along with a proton.'' Two clues must be combined: the cofactor stays bound and is regenerated in place (points away from dissociable coenzymes), and the chemistry is single-step hydride-transfer oxidation (points away from decarboxylation and transamination). (Choice A) is correct: FAD is tightly or covalently bound, is re-oxidized in place before the next turnover, and mediates hydride transfer during substrate oxidation (e.g., succinate to fumarate), matching both clues. (Choice B) NAD+ is incorrect: although NAD+ also oxidizes substrates by hydride transfer, the text notes it binds ''as a substrate and dissociates as a product after each catalytic cycle,'' so it leaves the active site rather than being re-oxidized in place; a student who keys only on ''removes a hydride'' overlooks that it does not stay bound. (Choice C) TPP is incorrect: TPP is tightly (covalently) bound, but it catalyzes the decarboxylation of alpha-keto acids by stabilizing a carbanion, not a hydride-transfer redox step; a student who keys only on ''stays bound'' but ignores the chemistry picks it. (Choice D) PLP is incorrect: PLP is covalently tethered via a Schiff base, but it catalyzes transamination, decarboxylation, and racemization of amino acids rather than two-electron hydride oxidation; a student who equates ''covalently attached'' with this enzyme''s role selects it. This is a Scientific Reasoning and Problem Solving question because you must apply the textbook''s criteria for binding behavior (tightly bound and regenerated in place versus dissociable) and reaction chemistry (hydride transfer versus decarboxylation or transamination) to identify the coenzyme from its functional description.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '42cba78b-3563-4f14-ac20-d17428b76e0f';
DELETE FROM question_distractor_metadata WHERE question_id = '42cba78b-3563-4f14-ac20-d17428b76e0f';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('42cba78b-3563-4f14-ac20-d17428b76e0f', 'B', 'adjacent_fact', 'right reaction chemistry (hydride oxidation) but wrong binding behavior — NAD+ dissociates as a co-substrate rather than staying bound and being regenerated in place'),
  ('42cba78b-3563-4f14-ac20-d17428b76e0f', 'C', 'misconception', 'keys on ''tightly bound cofactor'' but ignores reaction type — TPP is bound but does decarboxylation of alpha-keto acids, not hydride-transfer oxidation'),
  ('42cba78b-3563-4f14-ac20-d17428b76e0f', 'D', 'misconception', 'keys on ''covalently attached / Schiff base'' but wrong chemistry — PLP does transamination/decarboxylation of amino acids, not two-electron hydride oxidation');

-- Q8 [Cofactors, Coenzymes & Vitamins] modes=['B4'] ans=A medium skill2
UPDATE questions SET
  question_text = 'A dehydrogenase uses a small, vitamin-derived organic molecule to accept a hydride during each catalytic turnover. This molecule binds only weakly, dissociates from the active site after each reaction, and is replenished from a soluble cytoplasmic pool before it can be regenerated elsewhere in the cell. Given this binding behavior, the molecule is best described as functioning as which of the following?',
  options = '[{"label": "A", "text": "A co-substrate of the reaction"}, {"label": "B", "text": "A prosthetic group of the enzyme"}, {"label": "C", "text": "An allosteric effector of the enzyme"}, {"label": "D", "text": "The apoenzyme of the reaction"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The textbook states that coenzymes are small organic molecules, often vitamin-derived, that can either bind loosely and be released from the active site or bind tightly and remain associated. It emphasizes that loosely bound coenzymes ''can bind loosely with the enzyme and be released from the active site. As such, they are also considered substrates for the reaction,'' whereas ''tight-binding coenzymes are referred to as prosthetic groups.'' You must use the described binding behavior — weak binding, dissociation after each turnover, and replenishment from a free pool — to determine which functional role the molecule plays. (Choice A) is correct: because the molecule binds weakly, leaves the active site after each reaction, and is consumed and later regenerated in a separate step, it behaves like a co-substrate, exactly as the text describes for loosely bound, dissociable coenzymes such as NAD⁺. (Choice B) is incorrect: a prosthetic group is a coenzyme that is tightly or covalently bound and stays attached throughout the catalytic cycle (as with FAD); the scenario''s molecule dissociates each turnover, which is the opposite of prosthetic-group behavior. (Choice C) is incorrect: an allosteric effector regulates enzyme activity by binding a separate regulatory site to change conformation, not by participating chemically in the reaction; this molecule is chemically transformed by accepting a hydride, so it is a reactant, not a regulator. (Choice D) is incorrect: the apoenzyme is the protein enzyme lacking its cofactor, not the small organic molecule itself; the described molecule is the non-protein helper that binds the protein, so it cannot be the apoenzyme. This is a Scientific Reasoning and Problem Solving question because you must apply the definitions of loosely bound coenzymes and prosthetic groups to the molecule''s observed binding behavior rather than recall a label.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '4f93bedf-5397-4ba5-8ecc-c8c66d75e95d';
DELETE FROM question_distractor_metadata WHERE question_id = '4f93bedf-5397-4ba5-8ecc-c8c66d75e95d';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('4f93bedf-5397-4ba5-8ecc-c8c66d75e95d', 'B', 'misconception', 'assumes any organic cofactor is a tightly bound prosthetic group'),
  ('4f93bedf-5397-4ba5-8ecc-c8c66d75e95d', 'C', 'partial_truth', 'confuses a chemically participating cofactor with a regulatory allosteric ligand'),
  ('4f93bedf-5397-4ba5-8ecc-c8c66d75e95d', 'D', 'reversed_relationship', 'confuses the cofactor with the apoenzyme protein it binds');

-- Q9 [Cooperativity (T/R States, Sigmoidal Kinetics, Hill Coefficient)] modes=['A'] ans=A hard skill2
UPDATE questions SET
  question_text = 'A newly purified enzyme is a homotetramer with four identical subunits, each bearing one substrate-binding active site. A plot of initial velocity versus substrate concentration is sigmoidal, and a Hill-equation fit of the data returns a Hill coefficient of 2.8. What does the value 2.8 most accurately indicate about how this enzyme binds substrate?',
  options = '[{"label": "A", "text": "The four active sites bind substrate with positive cooperativity that is real but less than the theoretical maximum for four sites."}, {"label": "B", "text": "Roughly three of the four active sites are catalytically functional, and the fourth site does not bind substrate."}, {"label": "C", "text": "The four active sites bind substrate essentially independently, because the value falls well below the number of sites."}, {"label": "D", "text": "The four active sites bind substrate with negative cooperativity, since full positive cooperativity would give a value of 4."}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' For a protein with multiple binding sites, the Hill coefficient measures the degree of cooperativity, and it can range from 1 (no cooperativity, hyperbolic kinetics) up to the number of binding sites only in the limiting, idealized case of infinite cooperativity in which all sites fill in an all-or-none fashion. The textbook makes this explicit for hemoglobin: setting the exponent to 2.8 gives the best fit to the four-site oxygen data, and reaching n = 4 would require the interpretation that "all four oxygens bind at once" — "infinitely cooperative binding of oxygen" (lines 20609-20614) — which does not describe real binding. Thus a value between 1 and the site count reflects genuine but sub-maximal positive cooperativity. (Choice A) is correct: with four sites, a Hill coefficient of 2.8 sits between 1 and 4, indicating real positive cooperativity that is less than the all-or-none maximum, exactly as the source''s four-site fit of 2.8 illustrates (lines 20609-20614), and paralleling the real tetrameric Pfk A whose Hill coefficient is 3.3 rather than 4 (lines 21265-21266). (Choice B) is incorrect: this misreads the Hill coefficient as a literal count of active sites, but it is an empirical measure of cooperativity "determined to obtain the best fit to the binding data" (line 20642), not the number of functional subunits; all four sites are functional. (Choice C) is incorrect: a coefficient of 2.8 is well above 1, so the sites are clearly interacting, not independent — non-cooperative binding gives a Hill coefficient of 1 and a hyperbolic curve, as the equation reduces to Y = L/[KD + L] when n = 1 (line 20615), which contradicts the observed sigmoidal curve. (Choice D) is incorrect: negative cooperativity corresponds to a Hill coefficient below 1 (each binding event lowers remaining affinity, contrasted with positive cooperativity in the KNF model, lines 20854-20862); a value of 2.8 is greater than 1 and therefore signals positive, not negative, cooperativity, and the maximum of 4 represents infinite cooperativity rather than the threshold between positive and negative. This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between the Hill coefficient, the number of binding sites, and the degree of cooperativity — recognizing that 2.8 lies between 1 and 4 and therefore denotes sub-maximal positive cooperativity rather than a site count, independent binding, or negative cooperativity.',
  difficulty = 'hard',
  cognitive_skill = 2
WHERE id = '543c5343-4baf-4c36-844d-ed3f68a66bd9';
DELETE FROM question_distractor_metadata WHERE question_id = '543c5343-4baf-4c36-844d-ed3f68a66bd9';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('543c5343-4baf-4c36-844d-ed3f68a66bd9', 'B', 'misconception', 'reads Hill coefficient as a literal count of functional binding sites'),
  ('543c5343-4baf-4c36-844d-ed3f68a66bd9', 'C', 'misconception', 'assumes any value below the site count implies independent/non-cooperative binding'),
  ('543c5343-4baf-4c36-844d-ed3f68a66bd9', 'D', 'reversed_relationship', 'treats the site count as the boundary between positive and negative cooperativity, so n<sites means negative');

-- Q10 [Cooperativity (T/R States, Sigmoidal Kinetics, Hill Coefficient)] modes=['B3', 'B4', 'B5'] ans=B medium skill2
UPDATE questions SET
  question_text = 'A four-subunit enzyme binds its substrate at one site on each subunit. When the researcher fits the substrate-binding data to the Hill equation, the best fit gives a Hill coefficient of 2.3. What does this measured value indicate about how the four sites bind substrate?',
  options = '[{"label": "A", "text": "The sites bind with only negligible cooperativity, because a coefficient this far below four reflects almost no interaction between subunits"}, {"label": "B", "text": "The sites bind with positive cooperativity that is real but less than fully concerted across all four subunits"}, {"label": "C", "text": "The sites bind independently, since the coefficient is smaller than the number of subunits"}, {"label": "D", "text": "The sites bind with negative cooperativity, since the coefficient exceeds a value of one"}]'::jsonb,
  correct_answer = 'B',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The Hill coefficient is an empirically determined exponent that reports the degree of cooperativity: a value of 1 corresponds to independent, non-cooperative sites that give a hyperbolic curve, a value greater than 1 indicates positive cooperativity (each binding event raises the affinity of the remaining sites), and a value less than 1 indicates negative cooperativity. LibreTexts notes that the Hill equation reduces to the simple hyperbolic form "when n = 1 (as in the case with myoglobin)" (line 20615) and that fully concerted binding of all four oxygens at once would push n toward the number of sites, described as "infinitely cooperative binding" (lines 20611-20614). In practice the text reports intermediate values, such as a best-fit n of 2.8 for hemoglobin (line 20609) and a Hill coefficient of 3.3 for the allosteric enzyme Pfk A (line 21265), versus a coefficient "close to 1" for the non-cooperative Pfk B (lines 21266-21267). (Choice A) is incorrect: any coefficient above 1 already signals genuine interaction between the subunits, so a value of 2.3 reflects real, appreciable positive cooperativity rather than a negligible effect; this choice wrongly treats an intermediate n, simply because it sits well below 4, as evidence of essentially no interaction. (Choice B) is correct: n = 2.3 lies between 1 (independent sites) and 4 (the maximum for four fully concerted sites), so the sites bind with genuine positive cooperativity that is strong but short of the all-or-none, infinitely cooperative limit. (Choice C) is incorrect: independent binding gives a Hill coefficient of exactly 1, not merely any value below the subunit count; a coefficient of 2.3 is well above 1 and therefore rules out independence. (Choice D) is incorrect: negative cooperativity produces a Hill coefficient below 1, whereas a value above 1 indicates positive cooperativity, so this choice reverses the relationship between n and the sign of cooperativity. This is a Scientific Reasoning and Problem Solving question because you must apply the quantitative meaning of the Hill coefficient, relative to both 1 and the number of subunits, to interpret what a measured value of 2.3 reveals about the binding sites.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '5b5d0c92-a20a-438f-90d7-47cec440a9b2';
DELETE FROM question_distractor_metadata WHERE question_id = '5b5d0c92-a20a-438f-90d7-47cec440a9b2';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('5b5d0c92-a20a-438f-90d7-47cec440a9b2', 'A', 'misconception', 'intermediate Hill coefficient dismissed as too small to indicate meaningful cooperativity'),
  ('5b5d0c92-a20a-438f-90d7-47cec440a9b2', 'C', 'misconception', 'treats any n below the subunit count as evidence of independent (non-cooperative) sites'),
  ('5b5d0c92-a20a-438f-90d7-47cec440a9b2', 'D', 'reversed_relationship', 'assigns negative cooperativity to n greater than 1, inverting the sign convention');

-- Q11 [Enzyme Classification (EC Classes)] modes=['B4'] ans=B medium skill2
UPDATE questions SET
  question_text = 'During anaerobic metabolism, lactate dehydrogenase converts pyruvate to lactate. In this reaction, the carbonyl carbon of pyruvate becomes a hydroxyl-bearing carbon in lactate, and the coenzyme NADH is simultaneously converted to \(\text{NAD}^+\). Based on the chemistry of the reaction it catalyzes, lactate dehydrogenase is best classified as which of the following enzymes?',
  options = '[{"label": "A", "text": "Transferase"}, {"label": "B", "text": "Oxidoreductase"}, {"label": "C", "text": "Lyase"}, {"label": "D", "text": "Hydrolase"}]'::jsonb,
  correct_answer = 'B',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The Enzyme Commission classifies enzymes by the type of reaction they catalyze, and the textbook notes that the first EC digit designates one of six primary classes, where ''1'' stands for oxidoreductases. The textbook further describes redox reactions as those in which an oxidizing agent and a reducing agent exchange electrons, and it lists lactate dehydrogenase together with the NAD+/NADH coenzyme pair that carries those electrons. Here, pyruvate''s carbonyl carbon is reduced to a hydroxyl-bearing carbon while NADH is oxidized to \(\text{NAD}^+\), meaning electrons (as a hydride) pass from the coenzyme to the substrate. (Choice A) is incorrect: a transferase moves a discrete functional group (such as a phosphate or methyl group) from one molecule to another with no change in oxidation state; students often see the coenzyme changing form and mistake the hydride movement for group transfer, but the defining event here is a change in oxidation state, which is redox. (Choice B) is correct: the reaction couples reduction of the substrate to oxidation of the coenzyme, an electron-transfer (oxidation-reduction) reaction, which is the defining action of an oxidoreductase, the EC class that includes dehydrogenases. (Choice C) is incorrect: a lyase adds or removes a group non-hydrolytically, typically forming or breaking a double bond without redox chemistry; because the C=O is not eliminated but is instead reduced to C-OH with electrons supplied by NADH, this is not a simple lyase reaction. (Choice D) is incorrect: a hydrolase cleaves a bond by adding water, but no water is consumed and no bond is hydrolyzed here; the coenzyme, not \(\text{H}_2\text{O}\), is the second participant, so a student who assumes any two-substrate reaction involves water misclassifies it. This is a Scientific Reasoning and Problem Solving question because you must apply the definitions of the EC classes to the described chemistry, recognizing the coupled NADH oxidation and substrate reduction as an oxidation-reduction reaction rather than a group transfer.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '6041f683-baca-47e6-ac3e-ff8e34dc7784';
DELETE FROM question_distractor_metadata WHERE question_id = '6041f683-baca-47e6-ac3e-ff8e34dc7784';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('6041f683-baca-47e6-ac3e-ff8e34dc7784', 'A', 'misconception', 'mistakes hydride/coenzyme change for group transfer'),
  ('6041f683-baca-47e6-ac3e-ff8e34dc7784', 'C', 'misconception', 'assumes double-bond change means lyase'),
  ('6041f683-baca-47e6-ac3e-ff8e34dc7784', 'D', 'misconception', 'assumes second substrate must be water');

-- Q12 [Active Site, Lock-and-Key & Induced Fit] modes=['B4'] ans=A medium skill2
UPDATE questions SET
  question_text = 'An enzyme normally binds its substrate by the induced-fit mechanism. A researcher engineers a variant in which the binding pocket is permanently locked into the shape it adopts when the substrate is already bound, and this locked pocket is still exactly complementary to the free substrate. Compared with the original enzyme, how would the engineered variant most likely behave toward that same substrate?',
  options = '[{"label": "A", "text": "It would bind the substrate but no longer change shape upon contact"}, {"label": "B", "text": "It would refold each time before the substrate can approach the pocket"}, {"label": "C", "text": "It would force the substrate itself to adopt the pocket''s fixed shape"}, {"label": "D", "text": "It would fail to bind the substrate because the pocket is now rigid"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' LibreTexts contrasts the two binding models directly: in the lock-and-key model "the reactant fits the exact shape of the enzyme''s binding site," and substrates bind "without further modification to the enzyme''s shape," whereas in the induced-fit model "contact between the reactant and the protein changes the protein''s shape, allowing it to bind" and the shape changes "to better fit the substrate" (lines 731-733, 738-740). Locking the pocket into its substrate-bound conformation while keeping it complementary to the free substrate converts the enzyme from induced-fit behavior to lock-and-key behavior: the complementary shape is now pre-formed, so the substrate can still fit, but the enzyme no longer undergoes a conformational change when the substrate contacts it. (Choice A) is correct: because the pocket is pre-shaped to match the free substrate, binding can still occur, but the defining induced-fit event — a shape change on substrate contact — is eliminated, which is exactly the lock-and-key behavior the text describes as binding "without further modification to the enzyme''s shape" (line 738). (Choice B) is incorrect: it invents refolding before the substrate approaches; the textbook locates the induced-fit change at the moment of contact ("contact... changes the protein''s shape," line 732), not as repeated pre-binding refolding, and a pocket already complementary to the free substrate has no need to refold to admit it. (Choice C) is incorrect: it misplaces the conformational change onto the substrate; the text states the change is in "the protein''s shape" and "the enzyme''s shape" (lines 732, 739), not the substrate, so this reflects the common error of thinking the substrate remodels to the enzyme rather than the enzyme remodeling to the substrate. (Choice D) is incorrect: it assumes a rigid pocket cannot bind, but a rigid pocket already complementary to the substrate is precisely the lock-and-key situation in which "the reactant fits the exact shape of the enzyme''s binding site" (line 731) — rigidity does not prevent binding when the shape already matches. This is a Scientific Reasoning and Problem Solving question because you must apply the defining contrast between the induced-fit and lock-and-key models to predict how removing the substrate-induced conformational change alters an enzyme''s binding behavior.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '6ef19648-d986-4e1c-b959-75a87c920c92';
DELETE FROM question_distractor_metadata WHERE question_id = '6ef19648-d986-4e1c-b959-75a87c920c92';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('6ef19648-d986-4e1c-b959-75a87c920c92', 'B', 'misconception', 'misplaces the induced-fit conformational change as pre-binding refolding rather than a change triggered by substrate contact'),
  ('6ef19648-d986-4e1c-b959-75a87c920c92', 'C', 'reversed_relationship', 'reverses which molecule changes shape — thinks the substrate reshapes to the enzyme rather than the enzyme reshaping to the substrate'),
  ('6ef19648-d986-4e1c-b959-75a87c920c92', 'D', 'misconception', 'believes a rigid binding pocket cannot bind substrate, confusing rigidity with incompatibility even when the shape is already complementary');

-- Q13 [Lineweaver-Burk (Double-Reciprocal) Plots] modes=['A'] ans=A medium skill2
UPDATE questions SET
  question_text = 'A researcher measures initial velocities for a purified enzyme at several substrate concentrations, with and without a reversible inhibitor, and linearizes the data on a Lineweaver-Burk plot of \(1/v_0\) versus \(1/[S]\). Adding the inhibitor produces a family of lines that all share the same y-intercept but become progressively steeper, so their x-intercepts move closer to the origin as inhibitor concentration rises. Which type of inhibition is most consistent with this pattern?',
  options = '[{"label": "A", "text": "Competitive inhibition"}, {"label": "B", "text": "Uncompetitive inhibition"}, {"label": "C", "text": "Pure noncompetitive inhibition"}, {"label": "D", "text": "Irreversible inhibition"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' On a Lineweaver-Burk plot, the y-intercept equals \(1/V_{max}\) and the x-intercept equals \(-1/K_M\), so a change in either intercept reports a change in that kinetic parameter. The textbook states that for a competitive inhibitor \(V_M\) does not change but \(K_M\) appears to increase, so the lines share ''the same y-intercept (1/VM), and the x-intercepts (-1/KM) closer and closer to 0 as I increases,'' and that ''these intersecting plots are the hallmarks of competitive inhibition'' (lines 27846-27847). (Choice A) is correct: an unchanged y-intercept means \(V_{max}\) is preserved, while steeper slopes and x-intercepts approaching the origin mean apparent \(K_M\) rises — the exact signature of a competitive inhibitor, which binds the free enzyme and is outcompeted at high substrate. (Choice B) is incorrect: uncompetitive inhibition lowers both \(V_{max}\) and \(K_M\) proportionally, producing parallel lines with the same slope but a raised y-intercept (line 27760, 28123), not lines converging on a shared y-intercept. (Choice C) is incorrect: pure noncompetitive inhibition lowers \(V_{max}\) while leaving \(K_M\) unchanged, so the lines share the same x-intercept and diverge at a higher y-intercept — the mirror image of the described pattern (line 27766). (Choice D) is incorrect: irreversible inhibition permanently inactivates enzyme rather than reversibly competing for binding, so it cannot be overcome by raising substrate and is not classified by these reversible Lineweaver-Burk line families (line 27744-27746). This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between Lineweaver-Burk intercepts and \(V_{max}\)/\(K_M\) to translate a described change in plot geometry into the underlying inhibition mechanism.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '7f0d76f1-4581-4237-b71c-5ffca71dcb35';
DELETE FROM question_distractor_metadata WHERE question_id = '7f0d76f1-4581-4237-b71c-5ffca71dcb35';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('7f0d76f1-4581-4237-b71c-5ffca71dcb35', 'B', 'misconception', 'confuses uncompetitive parallel-line signature with competitive intersecting-line signature'),
  ('7f0d76f1-4581-4237-b71c-5ffca71dcb35', 'C', 'reversed_relationship', 'swaps which intercept stays fixed — thinks unchanged y-intercept means unchanged Vmax is the noncompetitive case'),
  ('7f0d76f1-4581-4237-b71c-5ffca71dcb35', 'D', 'partial_truth', 'picks a real inhibition category that is not diagnosable from a reversible Lineweaver-Burk line family');

-- Q14 [Enzyme Classification (EC Classes)] modes=['A', 'B4'] ans=A medium skill2
UPDATE questions SET
  question_text = 'During the first step of glycolysis, an enzyme takes the terminal phosphate group of ATP and attaches it, intact, to the 6-hydroxyl of glucose, yielding glucose-6-phosphate and ADP. No water is consumed, no atom changes its oxidation state, and the phosphate is neither made nor broken down but simply relocated from one molecule to another. Based on the chemistry described, this enzyme belongs to which EC class?',
  options = '[{"label": "A", "text": "Transferase"}, {"label": "B", "text": "Hydrolase"}, {"label": "C", "text": "Ligase"}, {"label": "D", "text": "Oxidoreductase"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The six EC classes are defined by the type of reaction catalyzed: the first digit of an enzyme''s EC number encodes its class, with class 2 (transferases) covering enzymes that move an intact functional group from a donor molecule to an acceptor (LibreTexts Biochemistry, lines 17894-17903, 28773). The textbook notes that a protein kinase ''covalently transfers a terminal phosphate from ATP'' to another molecule (line 347); the same logic applies here, where a phosphoryl group is relocated from ATP to glucose. (Choice A) is correct: the diagnostic feature is that a chemical group (the phosphoryl group) is carried from a donor (ATP) to an acceptor (glucose) with no change in oxidation state and no water involved, which is exactly the reaction type that defines transferases (kinases such as hexokinase are EC 2 phosphotransferases). (Choice B) is incorrect: this reflects the common misconception that any reaction consuming ATP is ''ATP hydrolysis,'' but a hydrolase cleaves a bond by inserting water, and here the phosphate is handed to glucose rather than released to a water molecule, so no hydrolysis occurs (LibreTexts, line 28773). (Choice C) is incorrect: ligases (EC 6) join two molecules using the energy of nucleotide triphosphate cleavage, but the diagnostic mark of a ligase is forming a new C-C, C-O, C-N, or C-S bond between two independent substrates; here glucose is simply modified by a group taken from ATP, not stitched to a second substrate, so the student who fixates on ''ATP is used up, so two things must be joined'' misclassifies it. (Choice D) is incorrect: oxidoreductases (EC 1) catalyze electron transfer between a donor and acceptor, but the stem explicitly states that no atom changes oxidation state, so associating this energy-metabolism step with redox chemistry is a mistake. This is a Scientific Reasoning and Problem Solving question because you must apply the definitions of the EC classes to a described reaction and recognize group transfer, rather than hydrolysis, joining, or redox, as the diagnostic feature.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '8233e99d-b761-4a4f-a396-b1a512bcd631';
DELETE FROM question_distractor_metadata WHERE question_id = '8233e99d-b761-4a4f-a396-b1a512bcd631';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('8233e99d-b761-4a4f-a396-b1a512bcd631', 'B', 'misconception', 'ATP consumption equals hydrolysis'),
  ('8233e99d-b761-4a4f-a396-b1a512bcd631', 'C', 'misconception', 'ATP-driven reaction must join two substrates (ligase)'),
  ('8233e99d-b761-4a4f-a396-b1a512bcd631', 'D', 'adjacent_fact', 'energy-metabolism reaction is assumed redox');

-- Q15 [Reversible Inhibition (Competitive, Noncompetitive, Uncompetitive, Mixed)] modes=['B3'] ans=C medium skill2
UPDATE questions SET
  question_text = 'A researcher characterizing an enzyme finds that a reversible inhibitor lowers \(V_{max}\) while leaving \(K_m\) unchanged, consistent with the inhibitor binding equally to both free enzyme and the enzyme–substrate complex at a site distinct from the active site. If the researcher then runs the assay at progressively higher substrate concentrations, the degree of inhibition would most likely be',
  options = '[{"label": "A", "text": "progressively reduced as the substrate concentration is raised."}, {"label": "B", "text": "reduced only once the substrate concentration approaches saturation."}, {"label": "C", "text": "essentially unchanged across the range of substrate concentrations."}, {"label": "D", "text": "progressively deepened as the substrate concentration is raised."}]'::jsonb,
  correct_answer = 'C',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The described inhibitor is a pure noncompetitive inhibitor: it binds free enzyme (E) and the enzyme–substrate complex (ES) with equal affinity at a site separate from the active site, forming a dead-end ESI complex. The text states that here ''as S increases to infinity, not all of E is converted to ES—there is a finite amount of ESI, even at infinite S,'' so \(V_{max}\) falls, while \(K_m\) ''will not change since I binds to both E and ES with the same affinity'' (lines 28239–28242). Because inhibitor and substrate occupy different sites, changing [S] does not shift the inhibitor''s binding equilibrium, so the fractional loss of activity is constant. (Choice A) is incorrect: being progressively overcome by more substrate is the signature of competitive inhibition, where inhibitor and substrate compete for the active site—the text notes ''competitive inhibitors can be overcome by increasing substrate concentration'' (lines 28564–28565)—not of a noncompetitive inhibitor that binds a separate site. (Choice B) is incorrect: this imagines relief switching on only near saturation, but the noncompetitive inhibitor binds E and ES with equal affinity at every substrate level, so no threshold effect exists and \(K_m\) stays unchanged. (Choice C) is correct: with equal binding to E and ES at a distinct site, raising [S] neither displaces the inhibitor nor perturbs its equilibrium, so the proportional inhibition stays constant while \(V_{max}\) remains suppressed. (Choice D) is incorrect: deepening inhibition with more substrate describes uncompetitive inhibition, where the inhibitor binds only ES so more substrate (more ES) means more inhibitor binding; a pure noncompetitive inhibitor binds E and ES equally, so extra substrate does not worsen inhibition. This is a Scientific Reasoning and Problem Solving question because you must apply the noncompetitive mechanism—equal binding to E and ES at a nonactive site—to predict that varying substrate concentration leaves the inhibition unchanged, distinguishing it from competitive and uncompetitive cases.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = '95306836-2497-4188-ab2c-26532c6c2910';
DELETE FROM question_distractor_metadata WHERE question_id = '95306836-2497-4188-ab2c-26532c6c2910';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('95306836-2497-4188-ab2c-26532c6c2910', 'A', 'misconception', 'treats all reversible inhibition as competitive/overcome-able by substrate'),
  ('95306836-2497-4188-ab2c-26532c6c2910', 'B', 'misconception', 'invents a substrate-threshold for relief, ignoring equal E/ES binding'),
  ('95306836-2497-4188-ab2c-26532c6c2910', 'D', 'misconception', 'confuses noncompetitive with uncompetitive (ES-only binding deepens with more substrate)');

-- Q16 [Cooperativity (T/R States, Sigmoidal Kinetics, Hill Coefficient)] modes=['B1', 'B3'] ans=B hard skill2
UPDATE questions SET
  question_text = 'A researcher studies a tetrameric enzyme that yields a sigmoidal rate-versus-substrate-concentration curve. Fitting the data to the Hill equation gives a Hill coefficient of 3, even though the enzyme has four substrate-binding sites (one per subunit). Which conclusion about this enzyme is best supported by the Hill coefficient?',
  options = '[{"label": "A", "text": "The four subunits bind substrate independently, and only three of them are catalytically active"}, {"label": "B", "text": "The subunits bind substrate with positive cooperativity, but the coupling between sites is not perfectly tight"}, {"label": "C", "text": "Substrate binding at one site lowers the affinity of the remaining sites, indicating negative cooperativity"}, {"label": "D", "text": "The enzyme requires exactly three substrate molecules to bind before any catalysis can occur"}]'::jsonb,
  correct_answer = 'B',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' A sigmoidal curve implies cooperative binding, and the Hill coefficient (n) is an empirical measure of that cooperativity: the textbook notes that the Hill coefficient is \"empirically determined to obtain the best fit to the binding data,\" and that a value of n = 1 corresponds to non-cooperative (hyperbolic) binding while n greater than 1 corresponds to positive cooperativity, where \"the next oxygen seems to bind with higher affinity (lower KD).\" The Hill coefficient is bounded above by the number of binding sites; only in the limit of \"infinitely cooperative\" (perfectly tight) coupling would n equal the number of sites, so a value between 1 and the site number reflects real but imperfect cooperativity. (Choice A) is incorrect: this reflects the misconception that the Hill coefficient counts the number of functional or active subunits, so n = 3 must mean three working sites; in fact n measures the degree of interaction between sites, not how many subunits are catalytically competent. (Choice B) is correct: because n = 3 is greater than 1, binding is positively cooperative, and because n = 3 is less than the four actual binding sites, the sites are not perfectly (infinitely) coupled — exactly what a non-integer or below-maximum Hill coefficient indicates. (Choice C) is incorrect: this reverses the relationship — negative cooperativity (each binding event lowering affinity for the next) is indicated by n less than 1, whereas n = 3 is greater than 1 and signals positive cooperativity. (Choice D) is incorrect: this misreads the Hill coefficient as a required binding stoichiometry, as if three substrates must be loaded before catalysis; n is a fitted cooperativity parameter, not a threshold count of molecules needed for the reaction to proceed. This is a Scientific Reasoning and Problem Solving question because you must apply the meaning of the Hill coefficient — its sign relative to 1 and its magnitude relative to the number of sites — to interpret the cooperative behavior of a multisubunit enzyme rather than recalling a definition.',
  difficulty = 'hard',
  cognitive_skill = 2
WHERE id = 'a4f64208-4253-48b0-8389-f693bd27cf17';
DELETE FROM question_distractor_metadata WHERE question_id = 'a4f64208-4253-48b0-8389-f693bd27cf17';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('a4f64208-4253-48b0-8389-f693bd27cf17', 'A', 'misconception', 'Hill coefficient counts active/functional subunits'),
  ('a4f64208-4253-48b0-8389-f693bd27cf17', 'C', 'reversed_relationship', 'n>1 misread as negative cooperativity'),
  ('a4f64208-4253-48b0-8389-f693bd27cf17', 'D', 'misconception', 'Hill coefficient read as required binding stoichiometry/threshold');

-- Q17 [Local Conditions: Temperature, pH & Salinity] modes=['B2', 'B3'] ans=A hard skill2
UPDATE questions SET
  question_text = 'An enzyme placed in a buffer of very high salt concentration loses nearly all of its catalytic activity. When the solution is later diluted back to physiological salt levels, much of the activity returns. Throughout, gel analysis shows the polypeptide is still full-length and its molecular weight is unchanged. Which mechanism best explains how the high-salt buffer abolished activity?',
  options = '[{"label": "A", "text": "The excess ions disrupt the noncovalent interactions that hold the enzyme in its folded shape, unfolding it while leaving every covalent bond intact"}, {"label": "B", "text": "The excess ions covalently attach to reactive side chains at the active site, chemically modifying the residues needed for catalysis"}, {"label": "C", "text": "The excess ions strengthen the folded structure so much that the core over-compacts and crushes the geometry of the active site"}, {"label": "D", "text": "The excess ions occupy the active site as competitive inhibitors, physically blocking substrate from reaching the catalytic residues"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The native (folded) state of an enzyme is held together by noncovalent forces: the text explains that ''noncovalent interactions... cause a protein to fold spontaneously to a unique 3D structure'' and names ''the different types of noncovalent interactions (ion-ion, H bonds, van der Waals)'' as the folding contributors (lines 14698, 14706), and it lists ''high concentrations of some salt solutions'' among the agents that ''unfold or denature proteins,'' precisely because such agents probe ''what stabilizes the tertiary structure of a native protein'' (lines 14702-14703), the tertiary structure being ''the overall 3D structure of the protein'' (line 11058). The stem''s three observations — the chain is full-length, its molecular weight is unchanged, and activity largely returns on simple dilution — mark this as reversible unfolding of the noncovalent framework, not a change to the covalent framework: the text distinguishes ''enzyme denaturation... [from] irreversible covalent modification'' (lines 27747-27748) and describes reversible denaturation in which ''refolding is initiated by diluting the protein into a solution without the denaturant'' (line 14025). (Choice A) is correct: high salt acts as a denaturant that disrupts the noncovalent interactions maintaining the folded 3D structure, so the enzyme unfolds and loses activity while every covalent bond stays intact — which is exactly why the full-length, unchanged-mass chain recovers function once the salt is diluted out. (Choice B) is incorrect: covalent modification of side chains is irreversible and is the mechanism of irreversible inhibitors, not of bulk salt (lines 27747-27748); it would not reverse on simple dilution and would be inconsistent with an unchanged covalent chain. (Choice C) is incorrect: this reverses the actual effect — high salt is named as a denaturing agent that destabilizes the native fold (lines 14702-14703), not one that strengthens or over-compacts it; nothing about excess salt drives productive extra compaction that ''crushes'' the active site. (Choice D) is incorrect: simple buffer ions occupying the active site as competitive inhibitors is a localized, active-site event, whereas the stem describes near-total loss of activity that reverses only on dilution of a denaturant; it confuses reversible active-site occupancy with global unfolding and does not explain why the intact chain must be diluted to recover function. This is a Scientific Reasoning and Problem Solving question because you must apply the distinction between covalent bonds and the noncovalent interactions that stabilize a fold to infer, from the reversibility and unchanged molecular weight, that high salt unfolds the enzyme by disrupting noncovalent contacts rather than altering its covalent structure.',
  difficulty = 'hard',
  cognitive_skill = 2
WHERE id = 'aea1afa0-e38e-420a-8343-0dcbbd8d7937';
DELETE FROM question_distractor_metadata WHERE question_id = 'aea1afa0-e38e-420a-8343-0dcbbd8d7937';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('aea1afa0-e38e-420a-8343-0dcbbd8d7937', 'B', 'misconception', 'conflates denaturation with irreversible covalent modification'),
  ('aea1afa0-e38e-420a-8343-0dcbbd8d7937', 'C', 'reversed_relationship', 'high salt strengthens/over-compacts rather than destabilizes structure'),
  ('aea1afa0-e38e-420a-8343-0dcbbd8d7937', 'D', 'misconception', 'attributes activity loss to active-site occupancy (competitive inhibition) instead of global unfolding');

-- Q18 [Catalytic Efficiency (kcat and kcat/Km)] modes=['B4', 'B5'] ans=B medium skill2
UPDATE questions SET
  question_text = 'An enzyme can act on two competing substrates, X and Y. A researcher measures the following steady-state constants for each: for substrate X, \(k_{cat} = 600\ \text{s}^{-1}\) and \(K_m = 3\times10^{-6}\ \text{M}\); for substrate Y, \(k_{cat} = 900\ \text{s}^{-1}\) and \(K_m = 3\times10^{-5}\ \text{M}\). In a single reaction the researcher adds both substrates at the same low concentration, far below either \(K_m\). Which substrate will the enzyme convert to product faster, and why?',
  options = '[{"label": "A", "text": "Substrate Y, because it has the larger turnover number"}, {"label": "B", "text": "Substrate X, because it has the larger specificity constant"}, {"label": "C", "text": "Substrate Y, because it reaches its maximum velocity at a higher substrate concentration"}, {"label": "D", "text": "Substrate X, because it has the smaller Michaelis constant"}]'::jsonb,
  correct_answer = 'B',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' When substrate concentration is far below \(K_m\), the Michaelis-Menten equation reduces to \(v_0 = (k_{cat}/K_m)[E_0][S]\), so the rate for each substrate is governed by its specificity constant \(k_{cat}/K_m\), the second-order rate constant that the textbook says ''describes how well an enzyme can differentiate between two different and competing substrates'' (libretexts-biochemistry.txt, lines 27368–27371). For two substrates at equal concentration, the ratio of their velocities equals the ratio of their \(k_{cat}/K_m\) values (line 28066–28067). Here \(k_{cat}/K_m\) for X is \(600 / (3\times10^{-6}) = 2\times10^{8}\ \text{M}^{-1}\text{s}^{-1}\), while for Y it is \(900 / (3\times10^{-5}) = 3\times10^{7}\ \text{M}^{-1}\text{s}^{-1}\); X''s value is about 6.7-fold larger, so X is converted faster. (Choice A) is incorrect: it applies the turnover number \(k_{cat}\), which the textbook defines as substrate molecules turned over per second (lines 27366–27367); \(k_{cat}\) alone determines the rate only near saturation, but here \([S] \ll K_m\), so Y''s higher \(k_{cat}\) does not make it the preferred substrate. (Choice C) is incorrect: it treats a higher \(K_m\) (Y saturates at higher \([S]\)) as an advantage, but at concentrations far below \(K_m\) a larger \(K_m\) means the enzyme captures substrate less efficiently, working against Y rather than favoring it. (Choice D) is incorrect: it correctly names X but for the wrong reason — the smaller \(K_m\) is only one factor, and substrate preference at low \([S]\) is set by the full ratio \(k_{cat}/K_m\), not \(K_m\) alone, so citing \(K_m\) in isolation could give the wrong answer whenever the substrate with the smaller \(K_m\) also has a much smaller \(k_{cat}\). (Choice B) is correct: at \([S] \ll K_m\) the specificity constant \(k_{cat}/K_m\) determines the rate, and X''s larger value makes it the faster-converted substrate. This is a Scientific Reasoning and Problem Solving question because you must apply the low-substrate limit of the Michaelis-Menten equation, compute and compare \(k_{cat}/K_m\) for each substrate, and identify which kinetic parameter governs preference between competing substrates.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = 'b3ac8fdc-1ea4-44a5-b0ff-eb42126b26f2';
DELETE FROM question_distractor_metadata WHERE question_id = 'b3ac8fdc-1ea4-44a5-b0ff-eb42126b26f2';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('b3ac8fdc-1ea4-44a5-b0ff-eb42126b26f2', 'A', 'misconception', 'higher kcat means preferred substrate regardless of concentration'),
  ('b3ac8fdc-1ea4-44a5-b0ff-eb42126b26f2', 'C', 'reversed_relationship', 'treats a higher Km as a kinetic advantage at low substrate'),
  ('b3ac8fdc-1ea4-44a5-b0ff-eb42126b26f2', 'D', 'misconception', 'right substrate, wrong parameter — uses Km alone instead of kcat/Km');

-- Q19 [Cofactors, Coenzymes & Vitamins] modes=['B1', 'B4'] ans=A hard skill2
UPDATE questions SET
  question_text = 'Two purified dehydrogenases are each assayed in dilute buffer that contains their substrate but no added cofactor. Enzyme X uses NAD⁺, which the researcher had to include in earlier assays and which does not co-purify with the protein. Enzyme Y uses a flavin (FAD) that co-purified with the protein through dialysis. Under these conditions Enzyme X carries out only a single round of turnover before stopping, whereas Enzyme Y continues to turn over substrate and produces product throughout the assay. Adding a small amount of NAD⁺ back to the Enzyme X assay restores sustained turnover. Which statement best accounts for the difference in behavior between the two enzymes?',
  options = '[{"label": "A", "text": "Enzyme X halts because its coenzyme leaves as a product and no fresh molecules are present in solution to replenish it"}, {"label": "B", "text": "Enzyme X halts because its coenzyme becomes covalently trapped in the active site after the first turnover"}, {"label": "C", "text": "Enzyme Y sustains activity because its flavin dissociates and is exchanged for a fresh molecule after each turnover"}, {"label": "D", "text": "Enzyme Y sustains activity because its flavin acts purely as a metal center and is never chemically altered"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' LibreTexts distinguishes two ways coenzymes associate with enzymes: some "bind loosely with the enzyme and be released from the active site," so they "are also considered substrates for the reaction," while others "may be tightly bound" prosthetic groups that "cannot dissociate easily." NAD⁺/NADP⁺ are described as "dissociable substrates/cofactors" whose "free enzyme is continually active since the NAD+ or NADP+ cofactor binds (as a substrate) and dissociates (as a product) after each catalytic cycle," whereas FAD "and its reduced form, FADH2, are tightly or covalently attached to an enzyme, so FAD must be regenerated in each catalytic cycle." (Choice A) is correct: NAD⁺ acts as a co-substrate that binds, is reduced to NADH, and leaves as a product; in a dilute assay with no NAD⁺ in solution, the enzyme completes one turnover using whatever was carried over and then stops until fresh NAD⁺ is supplied, exactly matching the single turnover followed by rescue on NAD⁺ addition. (Choice B) is incorrect: this invokes covalent trapping, which describes the tightly bound flavin of Enzyme Y, not the freely dissociating NAD⁺ of Enzyme X; a covalently trapped coenzyme would not be rescued simply by adding more coenzyme to solution. (Choice C) is incorrect: it applies the dissociable-substrate model to the wrong enzyme, since the co-purifying flavin does not exchange with solution; Enzyme Y keeps working because its bound flavin is re-oxidized in place, not swapped out. (Choice D) is incorrect: FAD is an organic coenzyme that is chemically reduced to FADH₂ and re-oxidized during turnover, so it is not an unchanged metal center; the "never chemically altered" description fits an inert metal ion, not a flavin. This is a Scientific Reasoning and Problem Solving question because you must apply the distinction between dissociable co-substrate coenzymes and enzyme-bound flavins to predict which enzyme stalls in a cofactor-free dilute assay and why replenishing solution coenzyme rescues it.',
  difficulty = 'hard',
  cognitive_skill = 2
WHERE id = 'c51a4e2b-a3db-46d2-bd34-bd4f703ff5c7';
DELETE FROM question_distractor_metadata WHERE question_id = 'c51a4e2b-a3db-46d2-bd34-bd4f703ff5c7';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('c51a4e2b-a3db-46d2-bd34-bd4f703ff5c7', 'B', 'reversed_relationship', 'attributes the bound-flavin (prosthetic) behavior to the dissociable NAD+ enzyme'),
  ('c51a4e2b-a3db-46d2-bd34-bd4f703ff5c7', 'C', 'reversed_relationship', 'applies the dissociable co-substrate model to the co-purifying flavin enzyme'),
  ('c51a4e2b-a3db-46d2-bd34-bd4f703ff5c7', 'D', 'misconception', 'confuses an organic redox flavin with an unchanging metal-ion cofactor');

-- Q20 [Michaelis-Menten Kinetics (Vmax, Km, Saturation)] modes=['B3', 'B5'] ans=A medium skill2
UPDATE questions SET
  question_text = 'An enzyme sample is already saturated with substrate, so its initial velocity has plateaued and adding more substrate produces no further increase in rate. A researcher still needs the reaction to run faster. Assuming the substrate remains at saturating levels and temperature and pH are held optimal, which change would raise the observed initial velocity?',
  options = '[{"label": "A", "text": "Doubling the amount of enzyme in the reaction"}, {"label": "B", "text": "Adding still more substrate to the reaction"}, {"label": "C", "text": "Using a substrate for which the enzyme has a lower \\(K_m\\)"}, {"label": "D", "text": "Nothing, because \\(V_{max}\\) is a fixed ceiling for this enzyme"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' At saturation the Michaelis-Menten model gives v = Vmax = kcat[E]0, which the textbook notes is ''zero order with respect to S and first order in E'' (LibreTexts Biochemistry, line 27089), and ''for all reactions, VM = kcatE0'' (line 27225). Because Vmax scales directly with the total enzyme concentration, the plateau rate is set by how much enzyme is present and its turnover number, not by substrate. (Choice A) is correct: since Vmax = kcat[E]0, doubling [E]0 doubles Vmax and therefore raises the saturated velocity; the rate at saturation is limited by enzyme quantity and turnover, which more enzyme directly increases (line 27225). (Choice B) is incorrect: this repeats the very instinct the stem shows fails — above saturation the rate is zero order in substrate, so ''when S >> KM, v = VM'' regardless of further additions (line 27089); a student who thinks ''more reactant always speeds a reaction'' picks this. (Choice C) is incorrect: lowering \(K_m\) raises affinity and shifts the low-[S] region of the curve, but it does not change the plateau; Vmax is independent of \(K_m\) and equals kcat[E]0 (line 27225), so at already-saturating [S] a tighter-binding substrate does not raise the ceiling. (Choice D) is incorrect: Vmax is not an immutable property of the enzyme species — it depends on how much enzyme is in the tube (Vmax = kcat[E]0, line 27225), so treating it as a fixed absolute ceiling ignores its dependence on [E]0. This is a Scientific Reasoning and Problem Solving question because you must apply the relationship Vmax = kcat[E]0 to reason that, at saturating substrate, only increasing enzyme (not substrate or affinity) can raise the observed velocity.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = 'c887e8b1-1426-42c7-89a0-d264e9e046d3';
DELETE FROM question_distractor_metadata WHERE question_id = 'c887e8b1-1426-42c7-89a0-d264e9e046d3';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('c887e8b1-1426-42c7-89a0-d264e9e046d3', 'B', 'misconception', 'more substrate always speeds the reaction (ignores zero-order/saturation regime)'),
  ('c887e8b1-1426-42c7-89a0-d264e9e046d3', 'C', 'reversed_relationship', 'confuses Km/affinity with maximal velocity; thinks tighter binding raises the plateau'),
  ('c887e8b1-1426-42c7-89a0-d264e9e046d3', 'D', 'misconception', 'treats Vmax as a fixed enzyme property independent of enzyme concentration');

-- Q21 [Active Site, Lock-and-Key & Induced Fit] modes=['B3', 'B5'] ans=A medium skill2
UPDATE questions SET
  question_text = 'Researchers crystallize an enzyme both alone and bound to its substrate. Comparing the two structures, they find that the geometry of the active site is measurably different in the bound form than in the free enzyme, with several catalytic residues repositioned closer to the substrate. Which conclusion is best supported by this observation?',
  options = '[{"text": "The enzyme follows an induced-fit model rather than a strict lock-and-key model", "label": "A"}, {"text": "The enzyme follows a strict lock-and-key model with a rigid preformed site", "label": "B"}, {"text": "The substrate changed its own shape to match the fixed active site", "label": "C"}, {"text": "The active site and substrate were not actually complementary to each other", "label": "D"}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The distinguishing feature of the two binding models is whether the enzyme changes shape on binding: in the induced-fit model "contact between the reactant and the protein changes the protein''s shape, allowing it to bind," with the substrate causing "the enzyme''s shape to change to better fit the substrate," whereas in the lock-and-key model "substrates bind to the enzyme''s active site without further modification to the enzyme''s shape" (LibreTexts 731-732, 738-739). The observation here — an active-site geometry that differs between the free and bound forms, with catalytic residues repositioned — is the experimental signature of a conformational change in the enzyme. (Choice A) is correct: a measured change in the enzyme''s active-site geometry upon substrate binding is precisely what induced fit predicts and what lock-and-key excludes, so the data support induced fit. (Choice B) is incorrect: a strict lock-and-key site is preformed and rigid and would show no change in enzyme shape between the free and bound structures, contradicting the observed repositioning of residues. (Choice C) is incorrect: it reflects the common misconception that flexibility means the substrate remolds itself to a static enzyme; in both accepted models the enzyme (not the substrate) is the flexible partner, and the data specifically report movement of the enzyme''s catalytic residues. (Choice D) is incorrect: an active site that reshapes to draw catalytic residues around the substrate is achieving complementarity, not lacking it — induced fit still ends in a complementary enzyme-substrate fit, so the conformational change does not imply the two were incompatible. This is a Scientific Reasoning and Problem Solving question because you must apply the defining criteria of the lock-and-key and induced-fit models to structural data and infer which model the evidence supports.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = 'c8f6b0d4-23af-4a8e-a01d-f6c9ed2e25c5';
DELETE FROM question_distractor_metadata WHERE question_id = 'c8f6b0d4-23af-4a8e-a01d-f6c9ed2e25c5';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('c8f6b0d4-23af-4a8e-a01d-f6c9ed2e25c5', 'B', 'reversed_relationship', 'confuses which model allows enzyme shape change'),
  ('c8f6b0d4-23af-4a8e-a01d-f6c9ed2e25c5', 'C', 'misconception', 'believes substrate reshapes to fit a static enzyme'),
  ('c8f6b0d4-23af-4a8e-a01d-f6c9ed2e25c5', 'D', 'misconception', 'thinks a conformational change means lost complementarity');

-- Q22 [Enzyme Regulation (Allosteric, Feedback, Covalent Modification, Zymogens)] modes=['B3'] ans=D medium skill2
UPDATE questions SET
  question_text = 'In a bacterial amino acid biosynthesis pathway, the end product of the pathway accumulates and slows the first enzyme of the pathway. Kinetic assays show that raising the substrate concentration to very high levels does NOT restore full enzyme activity, and after the assay the end product is recovered intact and the enzyme''s covalent structure is unchanged. Which mechanism best accounts for how this end product inhibits the enzyme?',
  options = '[{"label": "A", "text": "It binds the active site in place of the substrate, and adding excess substrate would out-compete it."}, {"label": "B", "text": "It forms a covalent bond to an amino acid side chain, locking the enzyme in a permanently inactive state."}, {"label": "C", "text": "It reacts with the incoming substrate and converts it to a form the enzyme cannot turn over."}, {"label": "D", "text": "It binds a site distinct from the active site and shifts the enzyme toward its inactive conformation."}]'::jsonb,
  correct_answer = 'D',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' Feedback inhibition is a classic allosteric mechanism: the end product of a pathway binds a site topographically distant from the active (orthosteric) site on the first enzyme and, by binding, redistributes the conformational ensemble to destabilize the active form and favor the inactive form (libretexts-biochemistry.txt, lines 31118-31121). The text gives the phosphoglycerate dehydrogenase example, in which the pathway end product serine "binds to an allosteric site on PGDH and inhibits it, a classic example of feedback inhibition of the first reaction of a pathway by the end product" (lines 31143-31144). Two clues in the stem force the mechanism: excess substrate does NOT overcome the inhibition (so binding is not at the substrate''s own site), and the inhibitor is recovered intact with the enzyme covalently unchanged (so the effect is noncovalent and reversible). (Choice A) is incorrect: this describes competitive inhibition at the active site, where substrate and inhibitor compete for the same site (lines 27808-27810), which excess substrate CAN overcome; students often conflate allosteric feedback with active-site competition, but the stem explicitly states high substrate fails to restore activity. (Choice B) is incorrect: covalent modification of a side chain would be a distinct, often durable regulatory mechanism, but the stem states the inhibitor is released intact and the enzyme''s covalent structure is unchanged, so no bond is formed. (Choice C) is incorrect: allostery regulates the enzyme itself by binding a distal site (lines 31118-31120), not by chemically transforming the substrate; the inhibitor is recovered unchanged, so it is not reacting with substrate. (Choice D) is correct: an allosteric (feedback) inhibitor binds a site distinct from the active site and shifts the enzyme toward its inactive conformation, consistent with reversible binding, substrate-insensitivity, and no covalent change (lines 31119-31121, 31143-31144). This is a Scientific Reasoning and Problem Solving question because you must apply the definition of allosteric feedback inhibition to the kinetic and structural observations and infer that a reversibly binding, substrate-insensitive end-product inhibitor acts through a distal conformational shift rather than active-site competition, covalent modification, or substrate alteration.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = 'cccd028b-13de-4a10-ba5a-e85718a0c745';
DELETE FROM question_distractor_metadata WHERE question_id = 'cccd028b-13de-4a10-ba5a-e85718a0c745';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('cccd028b-13de-4a10-ba5a-e85718a0c745', 'A', 'misconception', 'confuses allosteric feedback inhibition with active-site competitive inhibition'),
  ('cccd028b-13de-4a10-ba5a-e85718a0c745', 'B', 'misconception', 'confuses reversible allosteric binding with covalent modification'),
  ('cccd028b-13de-4a10-ba5a-e85718a0c745', 'C', 'misconception', 'believes inhibition acts on the substrate rather than on the enzyme');

-- Q23 [Enzyme Regulation (Allosteric, Feedback, Covalent Modification, Zymogens)] modes=['B1', 'B5'] ans=A medium skill2
UPDATE questions SET
  question_text = 'A multisubunit metabolic enzyme catalyzes a reaction whose rate versus substrate concentration follows a sigmoidal curve. When a small molecule that binds a site distinct from the active site is added at a fixed, saturating concentration, the enzyme''s activity is measured across a range of substrate concentrations. If this molecule is a heterotropic allosteric activator, how should the rate-versus-substrate curve change compared to the curve obtained without it?',
  options = '[{"label": "A", "text": "The curve shifts to the left, lowering the substrate concentration needed for half-maximal rate."}, {"label": "B", "text": "The curve shifts to the right, raising the substrate concentration needed for half-maximal rate."}, {"label": "C", "text": "The curve keeps its midpoint but rises to a higher maximal rate at saturating substrate."}, {"label": "D", "text": "The curve keeps its midpoint but loses its sigmoidal shape and becomes hyperbolic."}]'::jsonb,
  correct_answer = 'A',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' A heterotropic allosteric activator binds an allosteric (non-active) site and stabilizes the enzyme''s active R conformation, redistributing the T/R equilibrium toward R (line 31119-31121: allosteric regulation "engender[s] a conformational change... stabilizing an active conformation (allosteric activation)"; line 21111-21112: shifting "the equilibrium to the active R state"). Because the R state has higher apparent affinity for substrate, the activator raises the rate at sub-saturating substrate and lowers the substrate concentration needed for half-maximal rate, shifting the sigmoidal curve to the left — the mirror image of how inhibitory effectors on hemoglobin "shift the binding curve... to the right, lowering the apparent affinity" (line 20436). (Choice A) is correct: stabilizing the R state increases apparent substrate affinity, so the half-maximal point occurs at a lower substrate concentration and the curve moves left. (Choice B) is incorrect: shifting the curve to the right (higher half-maximal substrate, lower apparent affinity) is the effect of an allosteric inhibitor, not an activator — this reverses the direction of the modulation. (Choice C) is incorrect: this confuses a K-type effect with a V-type effect; a heterotropic activator of this enzyme changes apparent substrate affinity (the position of the curve), not the maximal catalytic rate reached at saturating substrate. (Choice D) is incorrect: an activator does not simply abolish cooperativity while leaving the midpoint fixed; stabilizing the R state shifts the equilibrium and moves the curve''s position, so the half-maximal substrate concentration decreases rather than staying the same. This is a Scientific Reasoning and Problem Solving question because you must apply the R/T equilibrium model to predict how stabilizing the active conformation repositions a sigmoidal rate-versus-substrate curve.',
  difficulty = 'medium',
  cognitive_skill = 2
WHERE id = 'd56cd755-9cb1-4532-81bc-a44e058752d3';
DELETE FROM question_distractor_metadata WHERE question_id = 'd56cd755-9cb1-4532-81bc-a44e058752d3';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('d56cd755-9cb1-4532-81bc-a44e058752d3', 'B', 'reversed_relationship', 'activator effect confused with inhibitor effect (curve shifts right)'),
  ('d56cd755-9cb1-4532-81bc-a44e058752d3', 'C', 'misconception', 'K-type vs V-type confusion (thinks activator raises Vmax)'),
  ('d56cd755-9cb1-4532-81bc-a44e058752d3', 'D', 'misconception', 'believes activation abolishes cooperativity without repositioning the curve');

-- Q24 [Enzyme Classification (EC Classes)] modes=['A', 'B4'] ans=B hard skill2
UPDATE questions SET
  question_text = 'A newly characterized enzyme catalyzes the formation of a covalent bond that fuses two separate small-molecule substrates into a single product. Kinetic studies show that for each product molecule formed, one molecule of ATP is broken down to ADP and inorganic phosphate, and no product accumulates when ATP is omitted from the reaction mixture. To which EC class does this enzyme most likely belong?',
  options = '[{"label": "A", "text": "Lyase"}, {"label": "B", "text": "Ligase"}, {"label": "C", "text": "Isomerase"}, {"label": "D", "text": "Transferase"}]'::jsonb,
  correct_answer = 'B',
  explanation = 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' Enzymes are grouped into EC classes by the type of reaction they catalyze, and the textbook defines ligases (EC6) as the class that carries out the ''condensation of two molecules into one'' (line 28743), a joining step that is energetically coupled to the cleavage of a nucleoside triphosphate; the text illustrates this with tRNA-acyl synthetase, which covalently links an amino acid to its tRNA in a reaction ''driven by ATP cleavage'' (lines 2100-2102). The two diagnostic clues here are that two separate substrates become one product AND that the bond-forming step is obligatorily coupled to ATP breakdown, and only the ligase class fits both. (Choice A) Lyase is incorrect: the textbook defines lyases (EC4) as catalyzing ''elimination forming a double bond'' (line 28704); a student may notice that a new bond is formed and recall that the reverse (synthetic) direction of a lyase also joins molecules, but lyases do so WITHOUT consuming ATP, so the strict ATP dependence rules this class out. (Choice B) is correct: joining two molecules into a single product with the reaction driven by ATP hydrolysis is the defining signature of a ligase (EC6), the ''condensation of two molecules into one'' class (line 28743), exactly as tRNA-acyl synthetase joins an amino acid to tRNA using ATP cleavage (lines 2100-2102). (Choice C) Isomerase is incorrect: isomerases (EC5) catalyze ''conversions of geometric, stereo- or constitutive isomers'' within a single molecule (line 28728), such as triose phosphate isomerase (line 25130); a student who treats isomerase as a generic ''rearrangement'' class overlooks that here two distinct substrates are combined rather than one molecule being internally reshaped, and no isomerization consumes ATP. (Choice D) Transferase is incorrect: transferases (EC2) catalyze the ''transfer/exchange of group from one molecule to another'' (line 28678), as when a kinase moves a phosphate onto a substrate; the presence of ATP tempts a student to assume a phosphate group is simply being transferred to the product, but here the ATP is consumed to energize the joining of the two substrates and the phosphate is released as free inorganic phosphate rather than ending up on the product, so the reaction is a ligation, not a group transfer. This is a Scientific Reasoning and Problem Solving question because you must apply the EC classification criteria to an unfamiliar reaction and infer that joining two molecules into one at the expense of ATP hydrolysis assigns the enzyme to the ligase class rather than the transferase or lyase class.',
  difficulty = 'hard',
  cognitive_skill = 2
WHERE id = 'da8f4561-e51c-4dba-9cc8-dd5ec79d0edf';
DELETE FROM question_distractor_metadata WHERE question_id = 'da8f4561-e51c-4dba-9cc8-dd5ec79d0edf';
