  ('e3dca137-4c0e-4ba4-b5cc-8da9d888e7a0', 'B', 'misconception', 'confuses_uncompetitive_signature_ignores_shared_y_intercept'),
  ('e3dca137-4c0e-4ba4-b5cc-8da9d888e7a0', 'C', 'reversed_relationship', 'swaps_which_intercept_maps_to_Vmax_vs_Km'),
  ('e3dca137-4c0e-4ba4-b5cc-8da9d888e7a0', 'D', 'misconception', 'assumes_both_parameters_change');

